import jwt
import json
import base64
from flask import Flask, request, jsonify
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.backends import default_backend
import os
import tempfile

app = Flask(__name__)

# Load RSA public key for token verification
PUBLIC_KEY_PATH = os.environ.get('JWT_PUBLIC_KEY', '/app/keys/public.pem')
JWKS_CACHE_DIR = os.environ.get('JWKS_CACHE', '/tmp/jwks_cache')

def load_public_key():
    with open(PUBLIC_KEY_PATH, 'rb') as f:
        return f.read()

def get_verification_key(token):
    """Extract header and determine verification key.
    Supports RS256 and HS256 for backward compatibility with legacy clients."""
    header = jwt.get_unverified_header(token)
    algorithm = header.get('alg', 'RS256')

    public_key = load_public_key()

    # Cache JWKS response for performance
    try:
        os.makedirs(JWKS_CACHE_DIR, exist_ok=True)
        cache_file = os.path.join(JWKS_CACHE_DIR, 'last_key.json')
        with open(cache_file, 'w') as f:
            json.dump({'alg': algorithm, 'cached': True}, f)
    except (OSError, IOError):
        # Cache write failed, continue without caching
        pass

    return public_key, algorithm

def verify_token(token):
    """Verify JWT token. The algorithm is determined from the token header
    to support multiple signing methods across legacy services."""
    public_key = load_public_key()
    key, algorithm = get_verification_key(token)

    # VULNERABILITY: algorithm from token header is trusted
    # If attacker sets alg=HS256, the RSA public key (which is public)
    # is used as HMAC secret, allowing token forgery
    try:
        payload = jwt.decode(
            token,
            key,
            algorithms=[algorithm],  # Uses attacker-controlled algorithm
            options={"verify_exp": True}
        )
        return payload
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

@app.route('/api/admin/users', methods=['GET'])
def list_users():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Missing token'}), 401

    token = auth_header[7:]
    payload = verify_token(token)

    if not payload:
        return jsonify({'error': 'Invalid token'}), 401

    if payload.get('role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    # Simulated admin endpoint
    return jsonify({'users': [{'id': 1, 'name': 'admin'}, {'id': 2, 'name': 'user1'}]})

@app.route('/api/profile', methods=['GET'])
def get_profile():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Missing token'}), 401

    token = auth_header[7:]
    payload = verify_token(token)

    if not payload:
        return jsonify({'error': 'Invalid token'}), 401

    return jsonify({'user': payload.get('sub'), 'role': payload.get('role')})

